 // #827: an optional progress sink; the row count is known, so the apply stage reports a real total.
 public ImportSummary Import(XmlSource source,IReadOnlyList<CatalogProduct> incoming,CancellationToken cancellationToken,XmlImportContext? context,IProgress<ImportProgressEvent>? progress)
 {
  cancellationToken.ThrowIfCancellationRequested();
